LEVELS_NOTE = 'This progression is illustrative: complex sentences do not define a level on their own. CEFR also considers comprehension, autonomy, fluency, accuracy, interaction and appropriateness.'


def build(c):
    k = c['k']; n = 24 + k
    a, b = c['cast']
    sp = {c['roles'][0]: {'name': a}, c['roles'][1]: {'name': b}}
    E = c['errs']; X = c['extra']
    sup = lambda s: [s]
    ch = c['chunks']; pri = [x['en'] for x in ch if x.get('pri')]
    P = []
    P.append(dict(t='rl_open', stage='warm', title=c['title'], pt=c['pt'], level='A1', unit=dict(UNIT(k), map=UNIT_MAP), situation=dict(text=c['sit'], scene=c['scene'], tod=c.get('tod', 'day'), cast=[a, b]), goal=c['goal'], canDo=c['canDo'], success=c['success'], think=c['think'],
     teach=teach(goal='Abrir a aula pela situação real, não pela regra.', solo=['Leia o objetivo em voz alta e peça que o estudante diga com as próprias palavras o que vai fazer hoje.', 'Pergunte “Think about it” antes de mostrar qualquer expressão.'], group=['Cada estudante diz UMA palavra que associa à situação de hoje.', 'Mostre os 4 critérios de sucesso: é a missão final da aula.'], extra=X[0:2], support=['Aceite respostas curtas ou em português na primeira rodada e reformule em inglês.'])))
