    pr = c['pron']
    P.append(dict(t='rl_pron', stage='gram', title='Pronunciation lab — natural American English', focus=pr['focus'], tip=pr['tip'], items=pr['items'], identify=pr['identify'], own=pr['own'],
     teach=teach(goal='UM só fenômeno: ' + pr['focus'] + '.', solo=['3 passagens: escutar e identificar → reproduzir ritmo e entonação → usar em frase com conteúdo próprio.', 'Modele devagar e normal; peça que o estudante bata palmas na sílaba forte.'], group=['Coro, depois duplas; circule ouvindo.', 'Cada estudante cria uma frase própria.'], answers=pr['answers'], errors=pr['errs'], support=['Reduza a velocidade e conte as batidas em voz alta.'])))
    P.append(dict(t='rl_challenge', stage=dict(solo='practice', group='gram'), title='Guided challenges', levels=[dict(h='Controlled practice — choose the best answer', items=c['ch1']), dict(h='Guided practice — complete, substitute and transform', items=c['ch2'])],
     teach=teach(goal='Do controlado ao guiado: completar, substituir e transformar antes da fala livre.', solo=['Peça que o estudante justifique cada resposta.', 'Se acertar rápido, peça a versão mais informal ou mais educada.'], group=['Resolvam em duplas e comparem antes de revelar.', 'Equipes: ponto por resposta justificada.'], answers=c['ch_answers'], extra=X[8:9], errors=E[6:7], support=['Ofereça o banco de palavras (chips) nas lacunas.'])))
    ro = c['role']
